WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (346::BIGINT, 'Parece que da la clase a lo que se le ocurra en el momento. No tiene cronograma definido, hay que estar recordándole enviar el material, todas las evaluaciones se lo deja al asistente que ni siquiera se pone de acuerdo con este. Poca comunicación ni instrucciones claras.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-05T00:00:00+00:00'::TIMESTAMPTZ, '91142658e8a957921676abdaa436207a49df6c32557fae13ee5477f64ba9a239'::TEXT, ARRAY[1186]::BIGINT[]),
    (346::BIGINT, 'Lo peor de constru'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2024-11-11T00:00:00+00:00'::TIMESTAMPTZ, '1011319aa9195a3b35ebd5b0d9fc9e51c3e03cc5bf734e5cfc4e04b301250059'::TEXT, ARRAY[1186]::BIGINT[]),
    (346::BIGINT, 'Es un profe demasiado disperso, tratamos de hablar con el para recibir indicaciones claras y su mejor respuesta fue regañarnos y decirnos que no eramos "chiquitos de kinder", los asistentes no se ponen de acuerdo con el profe y nadie sabe que hacer que hacer, no tiene un cronograma definido.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'ad1b25ec6ef9b83ab4e4538ceafdacd34debc815cc74ec564831acf48dcba577'::TEXT, ARRAY[1194]::BIGINT[]),
    (346::BIGINT, 'Semana 17 y no ha revisado casi nada. Las instrucciones son 0 claras y cambia todo de último momento, no se aprende mucho, siempre llega tarde a dar clases. Todo mal... Suerte ;)'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-05T00:00:00+00:00'::TIMESTAMPTZ, '0c5992cf9738bcdb433de8f616d3715d2232d0fe1f1ad08af8ce587cde40def6'::TEXT, ARRAY[1194]::BIGINT[]),
    (346::BIGINT, 'No es buen profe. No hay instrucciones por escrito de nada y cambia las cosas a conveniencia. Nunca hubo claridad de cómo hacer las cosas. Dura DEMASIADO para calificar. El examen es difícil. En definitiva no se lo recominedo, pero no es como tenga opción, así que prepárese para sufrir un ratillo :)'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2024-06-04T00:00:00+00:00'::TIMESTAMPTZ, '2944cb05ee91e7c29e40a348d663a4dd4cd6d47f9c045fbcaf8b26b24dfd979b'::TEXT, ARRAY[1194]::BIGINT[]),
    (346::BIGINT, 'Un profe muy más o menos.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, '55b2d3346db934a8c0ff237aa95ec41af8b1d01e5793c5c0543223a5714ee08b'::TEXT, ARRAY[1186]::BIGINT[]),
    (346::BIGINT, 'Clases muy largas, se extiende del horario. No tiene mecanismos buenos para dar clases, no es claro explicando, en resumen no es el peor profesor pero no es bueno. Prácticamente todas las calificaciones las dio un día antes de la entrega de actas, lo cual no permite hacer reclamos la verdad.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2021-07-03T00:00:00+00:00'::TIMESTAMPTZ, '551d0aea3e04c901021931d18e02a8872e8189681a8bbbd6afd5e0b6e788d4fd'::TEXT, ARRAY[1186]::BIGINT[]),
    (346::BIGINT, 'Las clases son muy largas, se extiende más del horario casi siempre, no es el más claro dando materia, no da casi notas se llega al final del curso talvez con solo la nota del primer examen, el último es en grupo para que formen un buen equipo'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2021-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'df5ee62a0935b425b66a98eea131b39e140c2cd48c53732c0396483c8701dd85'::TEXT, ARRAY[1186]::BIGINT[]),
    (346::BIGINT, 'Es un profesor irrespetuso que no le contesta a sus estudiantes los deja en visto. No explica nada bien y para lo que explica los examenes los hace demasido volados. Para ser un curso de topografia basico el examen lo hace como si uno dominara este campo. Semana 19 ni una tarea calificada.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-06-29T00:00:00+00:00'::TIMESTAMPTZ, '7c6b232e681824c38c68b1b879740462cf3de59d5dc4f862488f62d0140dee33'::TEXT, ARRAY[1186]::BIGINT[]),
    (346::BIGINT, 'Topo virtual: Es un profesor que no tiene la materia CLARA ni mucho menos tiene métodos de calificación adecuados. No se puede escapar de él, asi que preparese'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, 'd8a4e1ced27eca76d224ac598e7889f9b4ad965dccc76b05027cf2a41a124a50'::TEXT, ARRAY[1186]::BIGINT[]),
    (346::BIGINT, 'Es un curso fácil si se enfoca en mejorar la libreta conforme va avanzando. Pregunte bastante, el profe sabe mucho. Al comienzo el curso es un toque lento pero es un curso bonito. Los exámenes son un toque difíciles (busque exámenes pasados).'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-21T00:00:00+00:00'::TIMESTAMPTZ, '240d6fb508bf34b80a52fda6541156cb4ab7994bff43f5fddb8ad31d149df636'::TEXT, ARRAY[1186]::BIGINT[]),
    (346::BIGINT, 'Aveces no explica bien que tenemos que hacer pero es super amable cuando uno no entiende algo, es muy accesible para explicar con todo la gentileza del mundo'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Brinda apoyo']::TEXT[], '2019-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'c607c324cd66edd3cdfd1c19f6ec730ab50ea9373da273736bfe17d2ef1f8af9'::TEXT, ARRAY[1186]::BIGINT[]),
    (346::BIGINT, 'Hace el curso muy complicado para lo que debería ser, las prácticas se sale tipo 1 o 2 de la tarde y le encanta bajar puntos por cualquier cosa. Ve una línea mal hecha y quita 10 pts. Topo básica debería darla el profe William de aplicada, con él se aprende mucho más y las prácticas son decentes.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'd73c2a12e77f7dc418b45081d334259c20a5c9879379615442916d8d96e5f2ab'::TEXT, ARRAY[1186]::BIGINT[]),
    (346::BIGINT, 'Como persona es muy pura vida, no explica excelente pero se entiende, exámenes ni muy difíciles ni muy fáciles, califica bastante duro, totalmente binario'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'f5734e15da40289668c269783833af0b4957e9641558a61f8c46ae4789596bd8'::TEXT, ARRAY[1186]::BIGINT[]),
    (346::BIGINT, 'Regular. Es un profe muy pura vida, pero es medio regludo. Estudie bastante porque explica por encima, pero los examenes no son tan dificiles.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '27e5b1a750d7c2e90fe0edf0823b21574fda3204b23eb8ffaa325629bad760b8'::TEXT, ARRAY[1186]::BIGINT[]),
    (346::BIGINT, 'El profe no explica muy claro y cree que todo lo básico lo debe saber uno, que es cierto pero no se entiende que quiere que recordemos. Dura mucho entregando las pruebas. Él es pura vida. Es importante tener un buena cuadrilla.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2017-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'd3974955a19ad49b90c796143360582bec9337ac9ba9f7d3bac8c95cd056fabd'::TEXT, ARRAY[1186]::BIGINT[]),
    (346::BIGINT, 'Es un profesor que no explica claro, si el grupo le cae mal va a hacer los exámenes difíciles. Muchas veces llegaba malhumorado a clases y se desquitaba con los estudiantes. Tarda mucho en entregar evaluaciones'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Asistencia obligatoria']::TEXT[], '2017-11-29T00:00:00+00:00'::TIMESTAMPTZ, '2c5938fe247af9a015ceb38ceecb3d442fd21e2c230b6e1467be540237eb4d79'::TEXT, ARRAY[1186]::BIGINT[]),
    (346::BIGINT, 'El profe es buena gente, pero a veces no suele ser muy claro explicando y si uno le pregunta algo en las prácticas se enoja un poco, pero la verdad no es nada del otro mundo, si lo recomiendo'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'b994ae432906fa1bb8b355c59a8feaaa815f2903705fb3ff2080e3e2dffd62e8'::TEXT, ARRAY[1186]::BIGINT[]),
    (346::BIGINT, 'Le cuesta darse a entender por eso es un poco difícil ciertos temas sobre todo los de final de curso. Si el grupo le cae bien ayuda bastante y califica justo.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'd0a68569bb73d8903c0ee3756c538b1bd7066062a3ee48a7d57c1f427f518b72'::TEXT, ARRAY[1186]::BIGINT[]),
    (346::BIGINT, 'Es buen profe, ayuda si le preguntas. hay que seguir muy bien la instrucciones sino se molesta y te baja muchos puntos.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos proyectos grupales']::TEXT[], '2017-02-03T00:00:00+00:00'::TIMESTAMPTZ, '079fad705cec491e9b4fc60351604cbb24ffd4293615231a1109519af61a3198'::TEXT, ARRAY[1186]::BIGINT[]),
    (346::BIGINT, 'A la hora de explicar a veces no es tan claro, pero si consultas él le ayuda, hay que ser muy ordenado y seguir bien las instrucciones que de de lo contrario se moleta, es muy buena gente.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'a1f064a71975dfd4121d8f53f4d4b541b003729197f9644abdef61da8146e278'::TEXT, ARRAY[1186]::BIGINT[]),
    (346::BIGINT, 'A veces no se le entienden las instrucciones de la clase, pero si uno le pregunta, le aclara las dudas que la persona tenga. Es llevadero y califica más o menos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '6b704d9cf575c2cf900bf2f796cedb2cb08128a58d77a0e54799b8208edc6fd4'::TEXT, ARRAY[1186]::BIGINT[]),
    (346::BIGINT, 'No se da a entender y da instrucciones o muy claras.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, '52910d33465d0512219b8f7c997bf358070a1864ada7ba384683a8336e2614d4'::TEXT, ARRAY[1186]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
